package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

/**
 * Unit tests for TokenBuffer.writeNumber(double d).
 */
public class TokenBuffer_writeNumber_TriageGen0Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumber_PositiveDouble() throws IOException {
        double value = 123.45;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        // Verify that the generator received the number token and the value
        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_NegativeDouble() throws IOException {
        double value = -123.45;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_Zero() throws IOException {
        double value = 0.0;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_Infinity() throws IOException {
        double value = Double.POSITIVE_INFINITY;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_NegativeInfinity() throws IOException {
        double value = Double.NEGATIVE_INFINITY;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_NaN() throws IOException {
        double value = Double.NaN;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_LargeValue() throws IOException {
        double value = Double.MAX_VALUE;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_SmallValue() throws IOException {
        double value = Double.MIN_VALUE;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_WithCodec() throws IOException {
        // Test with a specific codec configuration
        mapper.configure(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN, true);
        tokenBuffer.setCodec(mapper);

        double value = 1.0;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = mock(JsonGenerator.class);
        tokenBuffer.serialize(gen);

        verify(gen).writeNumber(value);
    }

    @Test
    public void testWriteNumber_IntegrationWithParser() throws IOException {
        // Testing the ability to convert back to a parser after writing a number
        tokenBuffer.writeNumber(45.67);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.getCurrentToken());
        assertEquals(45.67, parser.getDoubleValue(), 0.0001);
    }
}
